import{z as A,x as s,o as t,c as p,q as r,j as B,D as E,d as e,s as o,S as n,b as l}from"./chunks/framework.C8m1ZpeB.js";const R=JSON.parse('{"title":"价值模型初始化","description":"","frontmatter":{"title":"价值模型初始化","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/value-model-init.md","filePath":"llm/value-model-init.md","lastUpdated":1791063341000}'),d={name:"llm/value-model-init.md"};function c(m,a,D,V,h,u){const i=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="价值模型初始化" tabindex="-1">价值模型初始化 <a class="header-anchor" href="#价值模型初始化" aria-label="Permalink to &quot;价值模型初始化&quot;">​</a></h1><div class="epigraph"><p>critic 与策略同规模时，它从哪份权重长出来，决定前几万步的 δ 是信息还是噪声。</p><footer>—— 对照 InstructGPT 的价值头；开源栈里常见的「从 RM 拷贝」与「从 SFT 拷贝」</footer></div><p><a href="/llm/ppo-clip-higher">上一课</a>改的是策略侧信任域。PPO 还要一个 \\(V_\\psi\\)。缺口是：<strong>随机初始化的价值头在长地平线上长期乱给 \\(\\delta_t\\)，GAE 再怎么调 \\(\\lambda\\) 也是在噪声上混合。</strong> 本课写 \\(V\\) 从哪来、是否与策略共享主干。<a href="/llm/grpo">GRPO</a> 去掉 critic，等于用组基线回避这个问题；本课只对还在用 PPO 的栈。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(V(s_t)\\) 要预测从当前前缀到结束的回报。\\(s_t\\) 是尚未写完的回答，回报却常是整段 RM 或校验器分数。从头训 \\(V\\)，等于在稀疏标签上拟合一个与策略同样大的回归器。常见做法：主干拷贝 SFT 或拷贝 RM，只随机一个标量头，再与策略联合训。拷贝 RM 的直觉是：RM 已经看见完整 \\(y\\) 的分数，前缀表示或许靠近价值；但 RM 训练目标是成对 logit，不是 \\(\\mathbb{E}[R\\mid s_t]\\)，迁移只是启发式。</p><p><span class="marginnote">数字实例：7B 策略配 7B critic，可训参数与策略一样多，而每个 prompt 只换来一条整段标量分数。让这种「一条轨迹一个数」的回归从随机权重长起，不如拷 SFT 或 RM 的主干、只随机最后那个标量头——大头表征复用，小头从头学。</span></p><p>共享主干（actor-critic 一头两用）省显存，价值损失会干扰语言表征，稳定性见已有的 AC 课。分开的 \\(V\\) 干净、贵。初始化选择在共享设定里更敏感：RM 头的特征可能带着长度捷径，价值会把「更长」学成高 \\(V\\)。</p><h3 id="初始化不是预训练价值函数" tabindex="-1">初始化不是预训练价值函数 <a class="header-anchor" href="#初始化不是预训练价值函数" aria-label="Permalink to &quot;初始化不是预训练价值函数&quot;">​</a></h3><p>没有「在离线轨迹上先做行为价值迭代再 PPO」的默认工序。LLM 的离线 \\(y\\) 来自旧策略，与当前 \\(\\pi\\) 不一致。最多做几个 epoch 的价值预热：冻结策略，用当前 rollout 回归 \\(V\\)。预热不足就开 clip，早期优势符号会错。</p><p><span class="marginnote">不要用 RM 分数直接当 \\(V\\) 而不回归。RM 看完整序列；\\(V\\) 必须在前缀上可评。把 RM 当 \\(V\\) 会泄漏未来 token。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配方 A：策略与 \\(V\\) 都从 SFT 初始化，分头，\\(V\\) 头小学习率。配方 B：\\(V\\) 从 RM 初始化（同词表同模板），策略从 SFT。配方 C：GRPO，无 \\(V\\)。预热：先采一批，只更新 \\(V\\)，直到解释方差不再涨，再联合。GAE 目标与价值 clip（独立于策略 clip）按 Schulman PPO 原文可选。</p><p><span class="marginnote">术语翻译：「解释方差」衡量 critic 的预测能解释多少回报波动——1 是完美，0 等于闭眼猜均值，负数是越猜越糟。预热到它不再上涨，才说明 \\(V\\) 已经从噪声里长出了信号，可以联合训练。</span></p>',13)),(t(),B(n,null,{default:E(()=>[o(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SFT%5B%22SFT%20%E6%9D%83%E9%87%8D%22%5D%20--%3E%20PI%5B%22%E7%AD%96%E7%95%A5%20%CF%80%22%5D%0A%20%20SFT%20--%3E%20VA%5B%22%E4%BB%B7%E5%80%BC%E5%A4%B4%E4%BB%8E%20SFT%22%5D%0A%20%20RM%5B%22RM%20%E6%9D%83%E9%87%8D%22%5D%20--%3E%20VB%5B%22%E4%BB%B7%E5%80%BC%E5%A4%B4%E4%BB%8E%20RM%22%5D%0A%20%20VA%20--%3E%20PPO%5B%22PPO%20%2B%20GAE%22%5D%0A%20%20VB%20--%3E%20PPO%0A%20%20NONE%5B%22%E4%B8%8D%E5%88%9D%E5%A7%8B%E5%8C%96%20V%22%5D%20--%3E%20GRPO%5B%22%E6%94%B9%20GRPO%20%E7%BB%84%E5%9F%BA%E7%BA%BF%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("p",null,"模板必须与策略一致。RM 若用另一套聊天模板，拷贝来的表征看的是「另一个字符串」，\\(V\\) 从第一步就偏。",-1)),a[4]||(a[4]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=l("p",null,"早期 \\(V\\) 若系统性高估，负优势被吞，策略不敢改；系统性低估，正优势泛滥，一步冲出 clip。从 RM 拷贝常见的偏置是长度：RM 爱长，\\(V\\) 在前缀阶段就预测高回报，模型更爱写长。从 SFT 拷贝则 \\(V\\) 接近常数，GAE 更接近蒙特卡洛，方差大但偏差小——长链上不一定更差。",-1)),(t(),B(n,null,{default:E(()=>[o(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20HI%5B%22V%20%E7%B3%BB%E7%BB%9F%E6%80%A7%E9%AB%98%E4%BC%B0%22%5D%20--%3E%20D1%5B%22%CE%B4%20%E8%A2%AB%E5%8E%8B%E6%88%90%E8%B4%9F%E5%80%BC%EF%BC%9A%E5%A4%84%E5%A4%84%E4%B8%8D%E5%8F%8A%E9%A2%84%E6%9C%9F%22%5D%0A%20%20D1%20--%3E%20A1%5B%22%E5%A5%BD%E5%8A%A8%E4%BD%9C%E7%9A%84%E4%BC%98%E5%8A%BF%E4%B9%9F%E8%A2%AB%E5%90%9E%E6%8E%89%22%5D%0A%20%20A1%20--%3E%20S1%5B%22%E7%AD%96%E7%95%A5%E4%B8%8D%E6%95%A2%E6%94%B9%EF%BC%8C%E5%AD%A6%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20LO%5B%22V%20%E7%B3%BB%E7%BB%9F%E6%80%A7%E4%BD%8E%E4%BC%B0%22%5D%20--%3E%20D2%5B%22%CE%B4%20%E6%B3%9B%E6%BB%A5%E6%88%90%E6%AD%A3%E5%80%BC%EF%BC%9A%E5%A4%84%E5%A4%84%E5%83%8F%E6%83%8A%E5%96%9C%22%5D%0A%20%20D2%20--%3E%20A2%5B%22%E4%BC%98%E5%8A%BF%E5%85%A8%E9%9D%A2%E5%81%8F%E5%A4%A7%22%5D%0A%20%20A2%20--%3E%20S2%5B%22%E4%B8%80%E6%AD%A5%E5%86%B2%E5%87%BA%20clip%EF%BC%8C%E8%AE%AD%E7%BB%83%E5%B4%A9%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">常见误区：以为「预热价值」是可省的仪式。预热不足就开 clip，早期 δ 全是噪声，优势符号大面积错误，策略在前几千步朝随机方向更新——这些坏方向的 KL 代价往往后面再多步也拉不回来。</span></p><p><span class="marginnote">价值损失权重过大时，共享主干会把语言模型练成回归器，KL 爆炸。权重是一等超参。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>可验证 0/1、组大小足够时，优先 GRPO，本课的初始化问题消失。偏好 RM + 真正需要逐步优势时，才值得养 critic。异步 rollout 下 \\(V\\) 版本落后，预热结论过期，需重算或提高 \\(\\lambda\\)。下一课处理奖励本身的尺度：白化，避免 \\(V\\) 去拟合漂移的 \\(r\\) 量纲。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>critic 应从 SFT 或 RM 拷贝主干并预热，不要随机长地平线回归。</li><li>RM 当 \\(V\\) 会泄漏未来；只能当初始化。</li><li>共享主干省显存、价值损失干扰表征。</li><li>组基线可绕开 \\(V\\)；需要逐步优势时再养 critic。</li><li>出处：Schulman PPO；Ouyang InstructGPT；开源 RLHF 栈的 critic 初始化实践。</li></ul>',6))])}const C=A(d,[["render",c]]);export{R as __pageData,C as default};
